    <path d="M -110 0 C -110 -40, -40 -40, 0 -20 C 40 0, 110 -40, 110 0 C 110 40, 40 40, 0 20 C -40 0, -110 40, -110 0 Z" fill="none" stroke="url(#knotGrad)" stroke-width="3" stroke-linecap="round"/>
    
